    long double fi, se;
    Val(double a=0.0, double b=0.0): fi(a), se(b) {}
};

Val merge(const Val& a, const Val& b) {
    return Val(a.fi + b.fi, a.se + b.se);
}

Val diff(const Val& a, const Val& b) {
    return Val(a.fi - b.fi, a.se - b.se);
}

Val scale(const Val& a, long double w) {
    return Val(a.fi * w, a.se * w);
}

Val quotient(const Val& a, long double w) {
    return Val(a.fi / w, a.se / w);
}

