import java.util.*;
import java.io.*;

public class Main {
    static class Val {
        double fi, se;
        Val(double a, double b) {
            this.fi = a;
            this.se = b;
        }
        Val() {
            this(0.0, 0.0);
        }
    }

    static Val merge(Val a, Val b) {
        return new Val(a.fi + b.fi, a.se + b.se);
    }

    static Val diff(Val a, Val b) {
        return new Val(a.fi - b.fi, a.se - b.se);
    }

    static Val scale(Val a, double w) {
        return new Val(a.fi * w, a.se * w);
    }

    static Val quotient(Val a, double w) {
        return new Val(a.fi / w, a.se / w);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        double[] probs = new double[n];
        for (int i = 0; i < n; i++) {
            probs[i] = sc.nextDouble();
        }

        for (int v = 0; v < n; v++) {
            int size = 1 << n;
            Val[] dp = new Val[size];
            for (int i = 0; i < size; i++) {
                dp[i] = new Val(0.0, 0.0);
            }
            for (int mask = 0; mask < size; mask++) {
                if (mask == 0) {
                    dp[mask] = new Val(1.0, 0.0);
                }
            }
            for (int mask = 1; mask < size; mask++) {
                if ((mask & (1 << v)) != 0) continue;
                Val sum = new Val(0.0, 0.0);
                double same = 0.0;
                for (int j = 0; j < n; j++) {
                    if (j != v && ((mask & (1 << j)) ) != 0) {
                        same += probs[j];
                        sum = merge(sum, scale(dp[mask ^ (1 << j)], probs[j]));
                    }
                }
                dp[mask] = quotient(sum, 1.0 - same);
            }
            Val total = new Val(1.0, 0.0);
            for (int mask = 1; mask < size; mask++) {
                if ((mask & (1 << v)) == 0) {
                    total = merge(total, dp[mask]);
                }
            }
            double alpha = (1.0 - total.se) / total.fi;
            Val bad = new Val(0.0, 0.0);
            for (int mask = 0; mask < size; mask++) {
                if ((mask & (1 << v)) != 0) continue;
                if (Integer.bitCount(mask) >= k) {
                    bad = merge(bad, dp[mask]);
                }
            }
            double result = 1.0 - (alpha * bad.fi + bad.se);
            System.out.printf("%.12f%s", result, (v + 1 == n) ? "\n" : " ");
        }
        sc.close();
    }
}
